1	/**
2	 * Alert Analytics & Incident Grouping Engine
3	 * 
4	 * Provides:
5	 * 1. Time-series analytics — alert frequency by type over 7/30 day windows
6	 * 2. Summary statistics — total alerts, most frequent type, peak hour, avg acknowledgment time
7	 * 3. Incident grouping — deduplicates same-type alerts within a time window into incidents
8	 * 4. Incident lifecycle — open → acknowledged → resolved with notes
9	 */
10	
11	import { createLogger } from '../_core/logger';
12	import { getDb } from '../db';
13	import { geometryAlertHistory, alertIncidents } from '../../drizzle/schema';
14	import { eq, and, gte, lte, desc, sql, count, avg, inArray } from 'drizzle-orm';
15	
16	const log = createLogger('alert-analytics');
17	
18	// ─── Types ────────────────────────────────────────────────────────
19	
20	export interface AlertFrequencyPoint {
21	  date: string;       // YYYY-MM-DD
22	  alertType: string;
23	  count: number;
24	}
25	
26	export interface AlertTrend {
27	  alertType: string;
28	  points: { date: string; count: number }[];
29	  total: number;
30	}
31	
32	export interface AlertSummaryStats {
33	  totalAlerts: number;
34	  totalUnacknowledged: number;
35	  totalIncidents: number;
36	  openIncidents: number;
37	  mostFrequentType: string | null;
38	  mostFrequentTypeCount: number;
39	  peakHour: number | null;       // 0-23
40	  peakHourCount: number;
41	  avgAcknowledgeTimeMs: number | null;
42	  alertsByType: { alertType: string; count: number; percentage: number }[];
43	  alertsBySeverity: { severity: string; count: number }[];
44	}
45	
46	export interface IncidentSummary {
47	  incidentId: string;
48	  alertType: string;
49	  sessionId: string | null;
50	  severity: string;
51	  status: string;
52	  alertCount: number;
53	  firstAlertAt: number;
54	  lastAlertAt: number;
55	  peakValue: number | null;
56	  peakThreshold: number | null;
57	  resolvedAt: number | null;
58	  resolvedBy: string | null;
59	  resolutionNotes: string | null;
60	  durationMs: number;
61	}
62	
63	export interface IncidentDetail extends IncidentSummary {
64	  alerts: {
65	    alertId: string;
66	    severity: string;
67	    value: number | null;
68	    threshold: number | null;
69	    message: string | null;
70	    firedAt: number;
71	    acknowledged: boolean;
72	  }[];
73	}
74	
75	// ─── Incident Grouping Config ─────────────────────────────────────
76	
77	/** Time window for grouping alerts into incidents (5 minutes) */
78	const INCIDENT_GROUPING_WINDOW_MS = 5 * 60 * 1000;
79	
80	// ─── Analytics Queries ────────────────────────────────────────────
81	
82	/**
83	 * Get alert frequency by type over a date range, bucketed by day.
84	 */
85	export async function getAlertFrequencyByType(options: {
86	  days: number;
87	  alertTypes?: string[];
88	}): Promise<AlertTrend[]> {
89	  try {
90	    const db = await getDb();
91	    const since = Date.now() - options.days * 24 * 60 * 60 * 1000;
92	
93	    // Query raw data from alert history
94	    let query = db.select({
95	      alertType: geometryAlertHistory.alertType,
96	      firedAt: geometryAlertHistory.firedAt,
97	    })
98	      .from(geometryAlertHistory)
99	      .where(gte(geometryAlertHistory.firedAt, since));
100	
101	    const rows = await query;
102	
103	    // Bucket by day and type
104	    const buckets = new Map<string, Map<string, number>>();
105	    const typeTotals = new Map<string, number>();
106	
107	    for (const row of rows) {
108	      if (options.alertTypes && options.alertTypes.length > 0) {
109	        if (!options.alertTypes.includes(row.alertType)) continue;
110	      }
111	      const date = new Date(Number(row.firedAt)).toISOString().split('T')[0];
112	      if (!buckets.has(row.alertType)) buckets.set(row.alertType, new Map());
113	      const typeBucket = buckets.get(row.alertType)!;
114	      typeBucket.set(date, (typeBucket.get(date) ?? 0) + 1);
115	      typeTotals.set(row.alertType, (typeTotals.get(row.alertType) ?? 0) + 1);
116	    }
117	
118	    // Generate date range
119	    const dates: string[] = [];
120	    for (let i = options.days - 1; i >= 0; i--) {
121	      const d = new Date(Date.now() - i * 24 * 60 * 60 * 1000);
122	      dates.push(d.toISOString().split('T')[0]);
123	    }
124	
125	    // Build trends
126	    const trends: AlertTrend[] = [];
127	    for (const [alertType, typeBucket] of buckets) {
128	      trends.push({
129	        alertType,
130	        total: typeTotals.get(alertType) ?? 0,
131	        points: dates.map(date => ({
132	          date,
133	          count: typeBucket.get(date) ?? 0,
134	        })),
135	      });
136	    }
137	
138	    // Sort by total descending
139	    trends.sort((a, b) => b.total - a.total);
140	    return trends;
141	  } catch (err) {
142	    log.error({ error: err instanceof Error ? err.message : String(err) }, 'Failed to get alert frequency');
143	    return [];
144	  }
145	}
146	
147	/**
148	 * Get comprehensive alert summary statistics.
149	 */
150	export async function getAlertSummaryStats(days: number = 30): Promise<AlertSummaryStats> {
151	  try {
152	    const db = await getDb();
153	    const since = Date.now() - days * 24 * 60 * 60 * 1000;
154	
155	    // Total alerts and unacknowledged
156	    const [totals] = await db.select({
157	      total: count(),
158	      unacknowledged: sql<number>`SUM(CASE WHEN ${geometryAlertHistory.acknowledged} = false THEN 1 ELSE 0 END)`,
159	    })
160	      .from(geometryAlertHistory)
161	      .where(gte(geometryAlertHistory.firedAt, since));
162	
163	    // Total incidents and open incidents
164	    const [incidentTotals] = await db.select({
165	      total: count(),
166	      open: sql<number>`SUM(CASE WHEN ${alertIncidents.status} = 'open' THEN 1 ELSE 0 END)`,
167	    })
168	      .from(alertIncidents)
169	      .where(gte(alertIncidents.firstAlertAt, since));
170	
171	    // Alerts by type
172	    const byType = await db.select({
173	      alertType: geometryAlertHistory.alertType,
174	      cnt: count(),
175	    })
176	      .from(geometryAlertHistory)
177	      .where(gte(geometryAlertHistory.firedAt, since))
178	      .groupBy(geometryAlertHistory.alertType)
179	      .orderBy(desc(count()));
180	
181	    // Alerts by severity
182	    const bySeverity = await db.select({
183	      severity: geometryAlertHistory.severity,
184	      cnt: count(),
185	    })
186	      .from(geometryAlertHistory)
187	      .where(gte(geometryAlertHistory.firedAt, since))
188	      .groupBy(geometryAlertHistory.severity);
189	
190	    // Peak hour analysis
191	    const allAlerts = await db.select({
192	      firedAt: geometryAlertHistory.firedAt,
193	    })
194	      .from(geometryAlertHistory)
195	      .where(gte(geometryAlertHistory.firedAt, since));
196	
197	    const hourCounts = new Array(24).fill(0);
198	    for (const alert of allAlerts) {
199	      const hour = new Date(Number(alert.firedAt)).getHours();
200	      hourCounts[hour]++;
201	    }
202	    let peakHour: number | null = null;
203	    let peakHourCount = 0;
204	    for (let h = 0; h < 24; h++) {
205	      if (hourCounts[h] > peakHourCount) {
206	        peakHour = h;
207	        peakHourCount = hourCounts[h];
208	      }
209	    }
210	
211	    // Average acknowledge time
212	    const ackAlerts = await db.select({
213	      firedAt: geometryAlertHistory.firedAt,
214	      acknowledgedAt: geometryAlertHistory.acknowledgedAt,
215	    })
216	      .from(geometryAlertHistory)
217	      .where(and(
218	        gte(geometryAlertHistory.firedAt, since),
219	        eq(geometryAlertHistory.acknowledged, true),
220	      ));
221	
222	    let avgAckTime: number | null = null;
223	    if (ackAlerts.length > 0) {
224	      const totalAckTime = ackAlerts.reduce((sum, a) => {
225	        if (a.acknowledgedAt) {
226	          return sum + (Number(a.acknowledgedAt) - Number(a.firedAt));
227	        }
228	        return sum;
229	      }, 0);
230	      avgAckTime = Math.round(totalAckTime / ackAlerts.length);
231	    }
232	
233	    const totalAlerts = totals?.total ?? 0;
234	    const mostFrequent = byType[0];
235	
236	    return {
237	      totalAlerts,
238	      totalUnacknowledged: Number(totals?.unacknowledged ?? 0),
239	      totalIncidents: incidentTotals?.total ?? 0,
240	      openIncidents: Number(incidentTotals?.open ?? 0),
241	      mostFrequentType: mostFrequent?.alertType ?? null,
242	      mostFrequentTypeCount: mostFrequent?.cnt ?? 0,
243	      peakHour,
244	      peakHourCount,
245	      avgAcknowledgeTimeMs: avgAckTime,
246	      alertsByType: byType.map(t => ({
247	        alertType: t.alertType,
248	        count: t.cnt,
249	        percentage: totalAlerts > 0 ? Math.round((t.cnt / totalAlerts) * 100) : 0,
250	      })),
251	      alertsBySeverity: bySeverity.map(s => ({
252	        severity: s.severity,
253	        count: s.cnt,
254	      })),
255	    };
256	  } catch (err) {
257	    log.error({ error: err instanceof Error ? err.message : String(err) }, 'Failed to get alert summary stats');
258	    return {
259	      totalAlerts: 0,
260	      totalUnacknowledged: 0,
261	      totalIncidents: 0,
262	      openIncidents: 0,
263	      mostFrequentType: null,
264	      mostFrequentTypeCount: 0,
265	      peakHour: null,
266	      peakHourCount: 0,
267	      avgAcknowledgeTimeMs: null,
268	      alertsByType: [],
269	      alertsBySeverity: [],
270	    };
271	  }
272	}
273	
274	// ─── Incident Grouping ───────────────────────────────────────────
275	
276	/**
277	 * Group a new alert into an existing open incident or create a new one.
278	 * Called after each alert is fired.
279	 */
280	export async function groupAlertIntoIncident(alert: {
281	  alertId: string;
282	  alertType: string;
283	  severity: 'warning' | 'critical';
284	  sessionId?: string | null;
285	  value?: number | null;
286	  threshold?: number | null;
287	  firedAt: number;
288	}): Promise<{ incidentId: string; isNew: boolean; alertCount: number }> {
289	  try {
290	    const db = await getDb();
291	    const windowStart = alert.firedAt - INCIDENT_GROUPING_WINDOW_MS;
292	
293	    // Find an existing open incident of the same type within the grouping window
294	    const existingIncidents = await db.select()
295	      .from(alertIncidents)
296	      .where(and(
297	        eq(alertIncidents.alertType, alert.alertType),
298	        eq(alertIncidents.status, 'open'),
299	        gte(alertIncidents.lastAlertAt, windowStart),
300	      ))
301	      .orderBy(desc(alertIncidents.lastAlertAt))
302	      .limit(1);
303	
304	    if (existingIncidents.length > 0) {
305	      const incident = existingIncidents[0];
306	      const newCount = incident.alertCount + 1;
307	      const newPeakValue = (alert.value !== null && alert.value !== undefined)
308	        ? Math.max(incident.peakValue ?? 0, alert.value)
309	        : incident.peakValue;
310	
311	      // Escalate severity if new alert is more severe
312	      const newSeverity = alert.severity === 'critical' ? 'critical' : incident.severity;
313	
314	      await db.update(alertIncidents)
315	        .set({
316	          alertCount: newCount,
317	          lastAlertAt: alert.firedAt,
318	          lastAlertId: alert.alertId,
319	          peakValue: newPeakValue,
320	          severity: newSeverity,
321	        })
322	        .where(eq(alertIncidents.id, incident.id));
323	
324	      log.info({
325	        incidentId: incident.incidentId,
326	        alertCount: newCount,
327	        alertType: alert.alertType,
328	      }, 'Alert grouped into existing incident');
329	
330	      return { incidentId: incident.incidentId, isNew: false, alertCount: newCount };
331	    }
332	
333	    // Create a new incident
334	    const incidentId = `inc_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
335	    await db.insert(alertIncidents).values({
336	      incidentId,
337	      alertType: alert.alertType,
338	      sessionId: alert.sessionId ?? null,
339	      severity: alert.severity,
340	      status: 'open',
341	      alertCount: 1,
342	      firstAlertAt: alert.firedAt,
343	      lastAlertAt: alert.firedAt,
344	      firstAlertId: alert.alertId,
345	      lastAlertId: alert.alertId,
346	      peakValue: alert.value ?? null,
347	      peakThreshold: alert.threshold ?? null,
348	    });
349	
350	    log.info({ incidentId, alertType: alert.alertType }, 'New incident created');
351	    return { incidentId, isNew: true, alertCount: 1 };
352	  } catch (err) {
353	    log.error({ error: err instanceof Error ? err.message : String(err) }, 'Failed to group alert into incident');
354	    // Return a synthetic incident ID so the alert isn't lost
355	    return { incidentId: `inc_error_${Date.now()}`, isNew: true, alertCount: 1 };
356	  }
357	}
358	
359	// ─── Incident Queries ─────────────────────────────────────────────
360	
361	/**
362	 * Get incidents with optional filtering.
363	 */
364	export async function getIncidents(options?: {
365	  status?: 'open' | 'acknowledged' | 'resolved';
366	  alertType?: string;
367	  severity?: 'warning' | 'critical';
368	  days?: number;
369	  limit?: number;
370	  offset?: number;
371	}): Promise<{ incidents: IncidentSummary[]; total: number }> {
372	  try {
373	    const db = await getDb();
374	    const limit = options?.limit ?? 50;
375	    const offset = options?.offset ?? 0;
376	    const conditions: any[] = [];
377	
378	    if (options?.status) {
379	      conditions.push(eq(alertIncidents.status, options.status));
380	    }
381	    if (options?.alertType) {
382	      conditions.push(eq(alertIncidents.alertType, options.alertType));
383	    }
384	    if (options?.severity) {
385	      conditions.push(eq(alertIncidents.severity, options.severity));
386	    }
387	    if (options?.days) {
388	      const since = Date.now() - options.days * 24 * 60 * 60 * 1000;
389	      conditions.push(gte(alertIncidents.firstAlertAt, since));
390	    }
391	
392	    const where = conditions.length > 0 ? and(...conditions) : undefined;
393	
394	    const [countResult] = await db.select({ total: count() })
395	      .from(alertIncidents)
396	      .where(where);
397	
398	    const rows = await db.select()
399	      .from(alertIncidents)
400	      .where(where)
401	      .orderBy(desc(alertIncidents.lastAlertAt))
402	      .limit(limit)
403	      .offset(offset);
404	
405	    const incidents: IncidentSummary[] = rows.map(r => ({
406	      incidentId: r.incidentId,
407	      alertType: r.alertType,
408	      sessionId: r.sessionId,
409	      severity: r.severity,
410	      status: r.status,
411	      alertCount: r.alertCount,
412	      firstAlertAt: Number(r.firstAlertAt),
413	      lastAlertAt: Number(r.lastAlertAt),
414	      peakValue: r.peakValue,
415	      peakThreshold: r.peakThreshold,
416	      resolvedAt: r.resolvedAt ? Number(r.resolvedAt) : null,
417	      resolvedBy: r.resolvedBy,
418	      resolutionNotes: r.resolutionNotes,
419	      durationMs: Number(r.lastAlertAt) - Number(r.firstAlertAt),
420	    }));
421	
422	    return { incidents, total: countResult?.total ?? 0 };
423	  } catch (err) {
424	    log.error({ error: err instanceof Error ? err.message : String(err) }, 'Failed to get incidents');
425	    return { incidents: [], total: 0 };
426	  }
427	}
428	
429	/**
430	 * Get incident detail with all grouped alerts.
431	 */
432	export async function getIncidentDetail(incidentId: string): Promise<IncidentDetail | null> {
433	  try {
434	    const db = await getDb();
435	
436	    const [incident] = await db.select()
437	      .from(alertIncidents)
438	      .where(eq(alertIncidents.incidentId, incidentId));
439	
440	    if (!incident) return null;
441	
442	    // Get all alerts within the incident's time window for the same type
443	    const alerts = await db.select({
444	      alertId: geometryAlertHistory.alertId,
445	      severity: geometryAlertHistory.severity,
446	      value: geometryAlertHistory.value,
447	      threshold: geometryAlertHistory.threshold,
448	      message: geometryAlertHistory.message,
449	      firedAt: geometryAlertHistory.firedAt,
450	      acknowledged: geometryAlertHistory.acknowledged,
451	    })
452	      .from(geometryAlertHistory)
453	      .where(and(
454	        eq(geometryAlertHistory.alertType, incident.alertType),
455	        gte(geometryAlertHistory.firedAt, incident.firstAlertAt),
456	        lte(geometryAlertHistory.firedAt, incident.lastAlertAt),
457	      ))
458	      .orderBy(desc(geometryAlertHistory.firedAt));
459	
460	    return {
461	      incidentId: incident.incidentId,
462	      alertType: incident.alertType,
463	      sessionId: incident.sessionId,
464	      severity: incident.severity,
465	      status: incident.status,
466	      alertCount: incident.alertCount,
467	      firstAlertAt: Number(incident.firstAlertAt),
468	      lastAlertAt: Number(incident.lastAlertAt),
469	      peakValue: incident.peakValue,
470	      peakThreshold: incident.peakThreshold,
471	      resolvedAt: incident.resolvedAt ? Number(incident.resolvedAt) : null,
472	      resolvedBy: incident.resolvedBy,
473	      resolutionNotes: incident.resolutionNotes,
474	      durationMs: Number(incident.lastAlertAt) - Number(incident.firstAlertAt),
475	      alerts: alerts.map(a => ({
476	        alertId: a.alertId,
477	        severity: a.severity,
478	        value: a.value,
479	        threshold: a.threshold,
480	        message: a.message,
481	        firedAt: Number(a.firedAt),
482	        acknowledged: a.acknowledged,
483	      })),
484	    };
485	  } catch (err) {
486	    log.error({ error: err instanceof Error ? err.message : String(err) }, 'Failed to get incident detail');
487	    return null;
488	  }
489	}
490	
491	/**
492	 * Resolve an incident with notes.
493	 */
494	export async function resolveIncident(
495	  incidentId: string,
496	  resolvedBy: string,
497	  notes?: string,
498	): Promise<boolean> {
499	  try {
500	    const db = await getDb();
501	    await db.update(alertIncidents)
502	      .set({
503	        status: 'resolved',
504	        resolvedAt: Date.now(),
505	        resolvedBy,
506	        resolutionNotes: notes ?? null,
507	      })
508	      .where(eq(alertIncidents.incidentId, incidentId));
509	
510	    log.info({ incidentId, resolvedBy }, 'Incident resolved');
511	    return true;
512	  } catch (err) {
513	    log.error({ error: err instanceof Error ? err.message : String(err) }, 'Failed to resolve incident');
514	    return false;
515	  }
516	}
517	
518	/**
519	 * Acknowledge an incident (intermediate state before resolution).
520	 */
521	export async function acknowledgeIncident(
522	  incidentId: string,
523	): Promise<boolean> {
524	  try {
525	    const db = await getDb();
526	    await db.update(alertIncidents)
527	      .set({ status: 'acknowledged' })
528	      .where(eq(alertIncidents.incidentId, incidentId));
529	
530	    log.info({ incidentId }, 'Incident acknowledged');
531	    return true;
532	  } catch (err) {
533	    log.error({ error: err instanceof Error ? err.message : String(err) }, 'Failed to acknowledge incident');
534	    return false;
535	  }
536	}
537	
538	// ─── Exports for testing ──────────────────────────────────────────
539	
540	export const INCIDENT_GROUPING_WINDOW = INCIDENT_GROUPING_WINDOW_MS;
